import type { Lang } from '../lib/lang'

/**
 * Image registry. Every image is referenced by key.
 * Files live in /public/media as `<file>-<width>.webp` and are generated by
 * `npm run assets` (tools/import_images.py). `focus` = default object-position.
 */

export interface Media {
  file: string
  widths: number[]
  width: number
  height: number
  alt: Record<Lang, string>
  focus?: string
}

const shot = (file: string, width: number, height: number, en: string, ar: string, focus?: string, widths?: number[]): Media => ({
  file,
  width,
  height,
  widths: widths ?? [900, width],
  alt: { en, ar },
  focus,
})

