export type MediaKey = keyof typeof defs
export const media: Record<MediaKey, Media> = defs

export function srcSet(m: Media) {
  return m.widths.map((w) => `/media/${m.file}-${w}.webp ${w}w`).join(', ')
}

export function src(m: Media, w?: number) {
  const width = w ?? m.widths[m.widths.length - 1]
  return `/media/${m.file}-${width}.webp`
}
